using System.Threading.Channels;

public static class Workers
{
    public static async Task<IReadOnlyList<TOut>> ProcessAsync<TIn, TOut>(
        IEnumerable<TIn> inputs, Func<TIn, Task<TOut>> work, int workers, int capacity)
    {
        if (workers < 1) throw new ArgumentOutOfRangeException(nameof(workers));
        if (capacity < 1) throw new ArgumentOutOfRangeException(nameof(capacity));

        var items = inputs.ToList();
        var results = new TOut[items.Count];
        var channel = Channel.CreateBounded<(int Index, TIn Input)>(capacity);
        using var stop = new CancellationTokenSource();

        async Task Produce()
        {
            try
            {
                for (int i = 0; i < items.Count; i++)
                    await channel.Writer.WriteAsync((i, items[i]), stop.Token);
            }
            catch (OperationCanceledException) { }
            finally
            {
                channel.Writer.TryComplete();
            }
        }

        async Task Consume()
        {
            try
            {
                await foreach (var (index, input) in channel.Reader.ReadAllAsync(stop.Token))
                    results[index] = await work(input);
            }
            catch (OperationCanceledException) when (stop.IsCancellationRequested) { }
            catch
            {
                stop.Cancel();
                throw;
            }
        }

        var producer = Produce();
        var consumers = Enumerable.Range(0, workers).Select(_ => Consume()).ToArray();
        try
        {
            await Task.WhenAll(consumers);
        }
        finally
        {
            stop.Cancel();
            await producer;
        }
        return results;
    }
}

unitTests:
Test("results keep the input order", () =>
{
    var output = Workers.ProcessAsync(new[] { 5, 1, 4, 2, 3 }, async n => { await Task.Delay(n * 10); return n * n; }, workers: 3, capacity: 2).Result;
    CheckEq(output, new[] { 25, 1, 16, 4, 9 });
});

Test("limited and overlapping", () =>
{
    int running = 0, peak = 0;
    var gate = new object();
    var output = Workers.ProcessAsync(Enumerable.Range(1, 12), async n =>
    {
        lock (gate) { running++; peak = Math.Max(peak, running); }
        await Task.Delay(20);
        lock (gate) running--;
        return n;
    }, workers: 3, capacity: 1).Result;
    CheckEq(output.Count, 12);
    Check(peak <= 3, $"{peak} calls ran at once");
    Check(peak > 1, "the work should overlap");
});

Test("errors and arguments", () =>
{
    var failing = Workers.ProcessAsync(new[] { 1, 2, 3, 4 }, async n => { await Task.Delay(5); if (n == 2) throw new InvalidOperationException("bad item"); return n; }, 2, 2);
    CheckThrows<InvalidOperationException>(() => failing.GetAwaiter().GetResult());
    CheckThrows<ArgumentOutOfRangeException>(() => Workers.ProcessAsync(new[] { 1 }, n => Task.FromResult(n), 0, 1).GetAwaiter().GetResult());
});

